#include <string>
#include <chrono>
#include <iomanip>
#include <sstream>
#include <stdexcept>

std::string generate_receive_log(const std::string &msg) {
    try {
        auto now = std::chrono::system_clock::now();
        auto now_time_t = std::chrono::system_clock::to_time_t(now);
        auto now_tm = *std::localtime(&now_time_t);

        std::ostringstream oss;
        oss << std::put_time(&now_tm, "%Y-%m-%dT%H:%M:%S");
        std::string timestamp = oss.str();

        // Basic sanitization: replace newline characters to prevent log injection
        std::string sanitized_msg = msg;
        size_t pos = 0;
        while ((pos = sanitized_msg.find('\n', pos)) != std::string::npos) {
            sanitized_msg.replace(pos, 1, "\\n");
            pos += 2;
        }

        return "[" + timestamp + "] Received: " + sanitized_msg;
    } catch (const std::exception &e) {
        // Handle any exceptions that might occur during time conversion
        throw std::runtime_error("Failed to generate log entry: " + std::string(e.what()));
    }
}
